net.coobird.thumbnailator.Thumbnails.Builder<java.awt.image.BufferedImage> builder = 
    net.coobird.thumbnailator.Thumbnails.of(sourceImage).size(50, 50);

// Call the API under test
builder.antialiasing(net.coobird.thumbnailator.resizers.configurations.Antialiasing.ON);

// Verify documented contract: calling multiple times throws IllegalStateException
boolean threwMultiple = false;
try {
    builder.antialiasing(net.coobird.thumbnailator.resizers.configurations.Antialiasing.OFF);
} catch (IllegalStateException e) {
    threwMultiple = true;
}
assert threwMultiple : "Calling antialiasing multiple times must throw IllegalStateException";

// Materialize the result to ensure the pipeline executes successfully with the configuration
java.awt.image.BufferedImage thumbnail = builder.asBufferedImage();
assert thumbnail.getWidth() <= 50 && thumbnail.getHeight() <= 50 : "Thumbnail dimensions should be within 50x50";

System.out.println("__CHECK__ antialiasing " + thumbnail.getWidth() + "x" + thumbnail.getHeight() + "_threw_" + threwMultiple);
